<template>
  <div class="watermark">
    <div class="watermark-content">
      <h2>水印组件</h2>
      <slot name="warp"></slot>
    </div>

    <div class="watermark-mask" ref="waterMarkMask">
      <div
        v-for="item in watermarks"
        :key="item.id"
        :style="item.style"
        class="watermark-mask-text"
      >
        {{ name }}
      </div>
    </div>
  </div>
</template>

<script>
export default {
  props: {
    name: {
      type: String,
      default: "vue-tools",
    }, // 水印显示内容
    nums: {
      type: Number,
      default: 30,
    }, // 水印数量【建议不超过50】
  },
  data() {
    return {
      maxRotation: 30,
      gridCellSize: 100, // 网格单元大小，可以根据实际情况调整
      watermarkSize: 50,
      watermarks: [],
    };
  },
  mounted() {
    this.generateWatermarks();
  },
  methods: {
    generateWatermarks() {
      const maskRect = this.$refs.waterMarkMask.getBoundingClientRect();
      const containerWidth = maskRect.width;
      const containerHeight = maskRect.height;
      const cols = Math.ceil(containerWidth / this.gridCellSize);
      const rows = Math.ceil(containerHeight / this.gridCellSize);

      const grid = Array.from({ length: rows }, () => Array(cols).fill(false));

      for (let i = 0; i < this.nums; i++) {
        let placed = false;
        while (!placed) {
          const col = Math.floor(Math.random() * cols);
          const row = Math.floor(Math.random() * rows);
          if (!grid[row][col]) {
            const left =
              col * this.gridCellSize +
              this.randomOffset(this.gridCellSize - this.watermarkSize);
            const top =
              row * this.gridCellSize +
              this.randomOffset(this.gridCellSize - this.watermarkSize);
            grid[row][col] = true;
            placed = true;

            const rotation = this.randomRotation();
            this.watermarks.push({
              id: i,
              style: {
                transform: `rotate(${rotation}deg)`,
                left: `${left}px`,
                top: `${top}px`,
              },
            });
          }
        }
      }
    },
    randomRotation() {
      return (
        Math.floor(Math.random() * (this.maxRotation * 2)) - this.maxRotation
      );
    },
    randomOffset(maxOffset) {
      return Math.floor(Math.random() * maxOffset);
    },
  },
};
</script>

